constexpr int64_t ANS_GEMM_TILING_HEAD_INTS = 16;
constexpr int64_t ANS_GEMM_SINGLE_M = 128;

optiling::TCubeTiling make_ans_cube_tiling(int64_t m, int64_t n0, int64_t n_pad, int64_t k, int64_t k0)
{
    using namespace matmul_tiling;
    auto *plat = platform_ascendc::PlatformAscendCManager::GetInstance();
    TORCH_CHECK(plat != nullptr, "ans_decode_gemm: PlatformAscendCManager unavailable");
    MatmulApiTiling tiling(*plat);
    tiling.SetAType(TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_BF16, false);
    tiling.SetBType(TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_BF16, true);
    tiling.SetCType(TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_BF16);
    tiling.SetBias(false);
    int64_t single_m = std::min(m, ANS_GEMM_SINGLE_M);
    tiling.SetOrgShape(m, n_pad, k);
    tiling.SetShape(single_m, n0, k);
    tiling.SetBufferSpace(-1, -1, -1);
    optiling::TCubeTiling cube;
    TORCH_CHECK(tiling.GetTiling(cube) != -1,
                "ans_decode_gemm: MatmulApiTiling failed for shape ", m, "x", n_pad, "x", k, " n0=", n0);
    return cube;
}

at::Tensor pack_ans_gemm_tiling(const int32_t *head10, int32_t m_pad, int32_t sys_bytes, int32_t cube_num,
                                int32_t flag_base, const optiling::TCubeTiling &cube)
{
    int64_t nbytes = ANS_GEMM_TILING_HEAD_INTS * static_cast<int64_t>(sizeof(int32_t)) +
                     static_cast<int64_t>(sizeof(cube));
    at::Tensor pack = at::zeros({nbytes}, at::TensorOptions().dtype(at::kByte).device(at::kCPU));
    auto *bytes = static_cast<uint8_t *>(pack.data_ptr());
    auto *head = reinterpret_cast<int32_t *>(bytes);
    std::memcpy(head, head10, 10 * sizeof(int32_t));
    head[0] = m_pad;
    head[10] = sys_bytes;
    head[11] = cube_num;
    head[12] = flag_base;
    std::memcpy(bytes + ANS_GEMM_TILING_HEAD_INTS * sizeof(int32_t), &cube, sizeof(cube));
    return pack;
}

