// Decode a gemm-tiled fixed-rate payload into a full [n_pad, k_pad] bf16
// tensor. No Cube, no cross-core flags -- this is the path used to verify the
// decode half of the fused kernel bit-exactly.
void ans_fixed_decode_tiles(at::Tensor &lplane, at::Tensor &eplane, at::Tensor &dplane, at::Tensor &sbase,
                            at::Tensor &wide_group, at::Tensor &wide_l, at::Tensor &wide_exp,
                            at::Tensor &wide_tile_off, at::Tensor &out)
{
    TORCH_CHECK(out.is_contiguous() && out.scalar_type() == at::kBFloat16,
                "ans_fixed_decode_tiles: out must be contiguous bfloat16");
    TORCH_CHECK(out.dim() == 2, "ans_fixed_decode_tiles: out must be 2D [n_pad, k_pad]");
    const int64_t n_pad = out.size(0);
    const int64_t k_pad = out.size(1);
    check_ans_fixed_planes(lplane, eplane, dplane, sbase, wide_group, wide_l, wide_exp, wide_tile_off, n_pad,
                           k_pad);

    auto *plat = platform_ascendc::PlatformAscendCManager::GetInstance();
    uint32_t cube_num = (plat != nullptr && plat->GetCoreNumAic() > 0) ? plat->GetCoreNumAic() : 20;
    // dbg -1 keys this on the no-Cube-tiling variant so it cannot collide with
    // the fused path's entry for the same shape.
    at::Tensor tiling = ans_fixed_tiling_cache().Get(0, n_pad, k_pad, 0, cube_num, -1, out.device());

    const c10_npu::OptionalNPUGuard npuGuard(out.device());
    aclrtStream stream = c10_npu::getCurrentNPUStream().stream();
    void *pl = lplane.data_ptr();
    void *pe = eplane.data_ptr();
    void *pd = dplane.data_ptr();
    void *ps = sbase.data_ptr();
    void *pwg = wide_group.data_ptr();
    void *pwl = wide_l.data_ptr();
    void *pwe = wide_exp.data_ptr();
    void *pwt = wide_tile_off.data_ptr();
    void *po = out.data_ptr();
    void *pt = tiling.data_ptr();

    at_npu::native::OpCommand cmd;
    cmd.Name("ans_fixed_decode_tiles");
    // Explicit value capture: [&] races the async OpCommand worker.
    cmd.SetCustomHandler([stream, pl, pe, pd, ps, pwg, pwl, pwe, pwt, po, pt, cube_num]() -> int {
        ans_fixed_decode_tiles_impl(stream, pl, pe, pd, ps, pwg, pwl, pwe, pwt, po, pt, cube_num);
        return 0;
    });
    cmd.Run();
}

// y = x @ W^T with W arriving as a fixed-rate payload, decoded on the AIV into
// a workspace panel that the Cube consumes.
//
// Correct, and slower than streaming bf16 -- see the header comment in the
// kernel. This exists for weight capacity, not for speed.
at::Tensor ans_fixed_decode_gemm(at::Tensor &x, at::Tensor &lplane, at::Tensor &eplane, at::Tensor &dplane,
                                 at::Tensor &sbase, at::Tensor &wide_group, at::Tensor &wide_l,
                                 at::Tensor &wide_exp, at::Tensor &wide_tile_off, int64_t n_pad,
                                 int64_t k_pad, int64_t dbg)
{
    TORCH_CHECK(x.dim() == 2 && x.is_contiguous() && x.scalar_type() == at::kBFloat16,
                "ans_fixed_decode_gemm: x must be 2D contiguous bfloat16");
    TORCH_CHECK(x.size(1) == k_pad, "ans_fixed_decode_gemm: x must be [M, ", k_pad, "], got k=", x.size(1));
    check_ans_fixed_planes(lplane, eplane, dplane, sbase, wide_group, wide_l, wide_exp, wide_tile_off, n_pad,
                           k_pad);

    const int64_t m = x.size(0);
    const int64_t m_pad = (m + 15) / 16 * 16;
    at::Tensor x_work = x;
    if (m_pad != m) {
        // at::empty, not at::zeros. Rows m..m_pad-1 are never read: in a GEMM
        // output row r depends only on A row r, and those rows are narrowed
        // off below. Zeroing them is a whole extra kernel launch, and at M = 1
        // -- every decode step -- it measured ~0.09 ms per linear.
        x_work = at::empty({m_pad, k_pad}, x.options());
        x_work.narrow(0, 0, m).copy_(x);
    }
    at::Tensor y = at::empty({m_pad, n_pad}, x.options());

    auto *plat = platform_ascendc::PlatformAscendCManager::GetInstance();
    uint32_t cube_num = (plat != nullptr && plat->GetCoreNumAic() > 0) ? plat->GetCoreNumAic() : 20;
    int64_t sys_ws = (plat != nullptr) ? static_cast<int64_t>(plat->GetLibApiWorkSpaceSize()) : 0;
    sys_ws = std::max<int64_t>(sys_ws, 16 * 1024 * 1024);
    sys_ws = (sys_ws + 511) / 512 * 512;
    TORCH_CHECK(sys_ws <= INT32_MAX, "ans_fixed_decode_gemm: sys workspace too large");

    at::Tensor tiling =
        ans_fixed_tiling_cache().Get(m_pad, n_pad, k_pad, sys_ws, cube_num, dbg, x.device());

    // ANS_FIXED_NSLOT panels per cube block, rotated against the Cube. Must
    // match NSLOT in csrc/kernels/ans_fixed_decode_gemm.cpp.
    int64_t user_ws = static_cast<int64_t>(cube_num) * ANS_FIXED_NSLOT * ANS_FIXED_TILE_N0 * k_pad *
                      static_cast<int64_t>(sizeof(uint16_t));
    // at::empty, not at::zeros: the kernel writes every panel byte before the
    // Cube reads it, and zeroing 40+ MB per call costs more than the GEMM.
    at::Tensor ws = at::empty({sys_ws + user_ws}, x.options().dtype(at::kByte));

    const c10_npu::OptionalNPUGuard npuGuard(x.device());
    aclrtStream stream = c10_npu::getCurrentNPUStream().stream();
    void *px = x_work.data_ptr();
    void *pl = lplane.data_ptr();
    void *pe = eplane.data_ptr();
    void *pd = dplane.data_ptr();
    void *ps = sbase.data_ptr();
    void *pwg = wide_group.data_ptr();
    void *pwl = wide_l.data_ptr();
    void *pwe = wide_exp.data_ptr();
    void *pwt = wide_tile_off.data_ptr();
    void *py = y.data_ptr();
    void *pws = ws.data_ptr();
    void *pt = tiling.data_ptr();

    at_npu::native::OpCommand cmd;
    cmd.Name("ans_fixed_decode_gemm");
    cmd.SetCustomHandler(
        [stream, px, pl, pe, pd, ps, pwg, pwl, pwe, pwt, py, pws, pt, cube_num]() -> int {
            ans_fixed_decode_gemm_impl(stream, px, pl, pe, pd, ps, pwg, pwl, pwe, pwt, py, pws, pt,
                                       cube_num);
            return 0;
        });
    cmd.Run();
    return (m_pad != m) ? y.narrow(0, 0, m).contiguous() : y;
}

